-- RoadMapperServer
-- An in-game tool for the place owner to trace the city's streets by hand,
-- since there's no real road data anywhere in this map for AI to navigate.
-- Walk or drive around, drop nodes along a street, and they're saved as real
-- Workspace instances - so they're part of the place file itself once you
-- save/publish, no DataStore needed.
--
-- Data lives in Workspace.RoadNetwork:
--   RoadNetwork/
--     Primary_1/   (Folder, attribute RoadType = "Primary"/"Secondary"/"Local")
--       1, 2, 3, ...  (small invisible Parts, in order, one per traced point)
-- Police AI (once built) will read this folder directly.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local NODE_SIZE = 1

local function isDev(player)
	if RunService:IsStudio() then
		return true
	end
	if game.CreatorType == Enum.CreatorType.Group then
		local ok, rank = pcall(player.GetRankInGroup, player, game.CreatorId)
		return ok and rank == 255
	end
	return player.UserId == game.CreatorId
end

local events = ReplicatedStorage:WaitForChild("Events")
local mapper = events:FindFirstChild("RoadMapper") or Instance.new("RemoteEvent")
mapper.Name = "RoadMapper"
mapper.Parent = events
local mapperQuery = ReplicatedStorage:WaitForChild("Functions"):FindFirstChild("RoadMapperQuery") or Instance.new("RemoteFunction")
mapperQuery.Name = "RoadMapperQuery"
mapperQuery.Parent = ReplicatedStorage.Functions

local network = workspace:FindFirstChild("RoadNetwork")
if not network then
	network = Instance.new("Folder")
	network.Name = "RoadNetwork"
	network.Parent = workspace
end

