local function buildSeedRoads()
	local built = 0
	for _, road in ipairs(SEED_ROADS) do
		if not network:FindFirstChild(road.name) then
			local folder = Instance.new("Folder")
			folder.Name = road.name
			folder:SetAttribute("RoadType", road.type)
			for i, xyz in ipairs(road.nodes) do
				local node = Instance.new("Part")
				node.Name = tostring(i)
				node.Size = Vector3.new(NODE_SIZE, NODE_SIZE, NODE_SIZE)
				node.Shape = Enum.PartType.Ball
				node.Transparency = 1
				node.CanCollide = false
				node.CanQuery = false
				node.Anchored = true
				node.CFrame = CFrame.new(xyz[1], xyz[2], xyz[3])
				node.Parent = folder
			end
			if road.lane then
				folder:SetAttribute("LaneWidth", road.lane)
			end
			folder:SetAttribute("AutoGenerated", true)
			folder.Parent = network
			built += 1
		end
	end
	return built
end

-- Only auto-generated roads are rebuilt each start. Roads you trace by hand with
-- the mapper (and save into the place) are never deleted any more.
-- Set Workspace.RoadNetwork attribute "DisableAutoRoads" = true to use only hand-traced roads.
for _,child in ipairs(network:GetChildren()) do
	if child:IsA("Folder") and child:GetAttribute("AutoGenerated") then
		child:Destroy()
	end
end

-- Roads made with the Road Editor plugin (saved in the place) replace the auto-generated set.
local handMade = 0
for _, child in ipairs(network:GetChildren()) do
	if child:IsA("Folder") and not child:GetAttribute("AutoGenerated") and child:FindFirstChild("1") then
		handMade += 1
	end
end
local seeded = if network:GetAttribute("DisableAutoRoads") or handMade > 0 then 0 else buildSeedRoads()
network:SetAttribute("AutoRoadCount", seeded)

-- One in-progress road per admin (their "pen" - the road they're currently adding to).
local sessions = {} -- [player] = { folder = Folder, count = n }

local function nextRoadName(roadType)
	local n = 1
	while network:FindFirstChild(roadType .. "_" .. n) do
		n += 1
	end
	return roadType .. "_" .. n
end

local function send(player, ...)
	mapper:FireClient(player, ...)
end

-- Footstep escort recorder. This is separate from vehicle roads: the dev can
-- equip the Footstep Route Recorder, walk the exact path an officer should
-- use, and click again to save it. The server prints a Lua-ready coordinate
-- table to Output so the route can be baked into a later build.
local escortRoot = workspace:FindFirstChild("EscortRoutes")
if not escortRoot then
	escortRoot = Instance.new("Folder")
	escortRoot.Name = "EscortRoutes"
	escortRoot.Parent = workspace
end
local escortSessions = {} -- [player] = {folder=Folder,count=n}

local function nextEscortName()
	local n = 1
	while escortRoot:FindFirstChild("Escort_" .. n) do n += 1 end
	return "Escort_" .. n
end

local function newEscort(player)
	local old = escortSessions[player]
	if old and old.folder then old.folder:Destroy() end
	local folder = Instance.new("Folder")
	folder.Name = nextEscortName()
	folder:SetAttribute("RouteType", "OfficerEscort")
	folder.Parent = escortRoot
	escortSessions[player] = {folder = folder, count = 0}
	send(player, "EscortSession", folder.Name, 0)
	print(("[RoadMapperServer] FOOTSTEP START: %s -> %s"):format(player.Name, folder.Name))
end

local function addEscortNode(player, position)
	local session = escortSessions[player]
	if not session or typeof(position) ~= "Vector3" then return end
	session.count += 1
	local node = Instance.new("Part")
	node.Name = tostring(session.count)
	node.Size = Vector3.new(0.6, 0.6, 0.6)
	node.Shape = Enum.PartType.Ball
	node.Transparency = 1
	node.CanCollide = false
	node.CanQuery = false
	node.Anchored = true
	node.CFrame = CFrame.new(position)
	node.Parent = session.folder
	send(player, "EscortNode", session.folder.Name, session.count, position)
end

local function finishEscort(player)
	local session = escortSessions[player]
	if not session then return end
	if session.count < 2 then
		local name = session.folder.Name
		session.folder:Destroy()
		escortSessions[player] = nil
		send(player, "EscortDiscarded", name)
		return
	end
	local out = {}
	for i = 1, session.count do
		local node = session.folder:FindFirstChild(tostring(i))
		if node then
			table.insert(out, ("{%.2f, %.2f, %.2f}"):format(node.Position.X, node.Position.Y, node.Position.Z))
		end
	end
	print(("[RoadMapperServer] FOOTSTEP ROUTE %s (%d nodes) = { %s }"):format(session.folder.Name, session.count, table.concat(out, ", ")))
	send(player, "EscortFinished", session.folder.Name, session.count)
	escortSessions[player] = nil
end

local function cancelEscort(player)
	local session = escortSessions[player]
	if not session then return end
	local name = session.folder.Name
	session.folder:Destroy()
	escortSessions[player] = nil
	send(player, "EscortDiscarded", name)
end

local function newRoad(player, roadType)
	if roadType ~= "Primary" and roadType ~= "Secondary" and roadType ~= "Local" then
		return
	end
	local folder = Instance.new("Folder")
	folder.Name = nextRoadName(roadType)
	folder:SetAttribute("RoadType", roadType)
	folder.Parent = network
	sessions[player] = { folder = folder, count = 0 }
	send(player, "Session", folder.Name, roadType, 0)
end

local function addNode(player, position)
	local session = sessions[player]
	if not session or typeof(position) ~= "Vector3" then
		return
	end
	session.count += 1
	local node = Instance.new("Part")
	node.Name = tostring(session.count)
	node.Size = Vector3.new(NODE_SIZE, NODE_SIZE, NODE_SIZE)
	node.Shape = Enum.PartType.Ball
	node.Transparency = 1 -- invisible to everyone; the admin client draws its own overlay
	node.CanCollide = false
	node.CanQuery = false
	node.Anchored = true
	node.CFrame = CFrame.new(position)
	node.Parent = session.folder
	send(player, "NodeAdded", session.folder.Name, session.count, position)
end

local function undoNode(player)
	local session = sessions[player]
	if not session or session.count == 0 then
		return
	end
	local node = session.folder:FindFirstChild(tostring(session.count))
	if node then
		node:Destroy()
	end
	session.count -= 1
	send(player, "NodeRemoved", session.folder.Name, session.count + 1)
end

local function finishRoad(player)
	local session = sessions[player]
	if not session then
		return
	end
	if session.count < 2 then
		session.folder:Destroy() -- a "road" with 0-1 points isn't useful; discard it
		send(player, "Discarded", session.folder.Name)
	else
		send(player, "Finished", session.folder.Name, session.count)
	end
	sessions[player] = nil
end

local function deleteRoad(player, roadName)
	local folder = network:FindFirstChild(roadName)
	if folder then
		folder:Destroy()
		send(player, "Deleted", roadName)
	end
end

local function listRoads()
	local roads = {}
	for _, folder in ipairs(network:GetChildren()) do
		local nodes = {}
		local i = 1
		while true do
			local node = folder:FindFirstChild(tostring(i))
			if not node then
				break
			end
			table.insert(nodes, node.Position)
			i += 1
		end
		local roadType = folder:GetAttribute("RoadType") or folder.Name:match("^(%a+)_") or "Local"
		table.insert(roads, { name = folder.Name, roadType = roadType, nodes = nodes })
	end
	return roads
end


---------------------------------------------------------------------------
-- ROAD MAPPER V2.1 -- explicit directional lane topology
-- Trace orientation defines forward travel.  Lane counts are persisted as
-- road attributes, so later traffic code never has to guess road direction.
---------------------------------------------------------------------------
local junctionRoot=network:FindFirstChild("Junctions") or Instance.new("Folder")
junctionRoot.Name="Junctions";junctionRoot.Parent=network
local v2Sessions={}

local function safeRoadName(s)
	s=tostring(s or ""):gsub("[^%w_%-%s]",""):gsub("%s+","_")
	return s:sub(1,48)
end
local function newRoadV2(player,data)
	if typeof(data)~="table" then return end
	local rt=data.roadType
	if rt~="Primary" and rt~="Secondary" and rt~="Local" then return end
	local requested=safeRoadName(data.name)
	local name=(requested~="" and not network:FindFirstChild(requested)) and requested or nextRoadName(rt)
	local f=Instance.new("Folder");f.Name=name;f.Parent=network
	f:SetAttribute("RoadType",rt);f:SetAttribute("MapperVersion",2);f:SetAttribute("IsRoadV2",true)
	f:SetAttribute("SpeedLimit",math.clamp(tonumber(data.speedLimit) or 25,5,120))
	f:SetAttribute("LaneWidth",math.clamp(tonumber(data.laneWidth) or 3.4,2,8))
	f:SetAttribute("ForwardLanes",math.clamp(math.floor(tonumber(data.forwardLanes) or 1),0,4))
	f:SetAttribute("ReverseLanes",math.clamp(math.floor(tonumber(data.reverseLanes) or 1),0,4))
	f:SetAttribute("MedianWidth",math.clamp(tonumber(data.medianWidth) or 0,0,40))
	f:SetAttribute("TraceDefinesForward",true)
	v2Sessions[player]={folder=f,count=0}
	send(player,"RoadSessionV2",name,rt)
end
local function addNodeV2(player,pos)
	local s=v2Sessions[player];if not s or typeof(pos)~="Vector3" then return end
	if s.count>0 then
		local prev=s.folder:FindFirstChild(tostring(s.count))
		if prev and (prev.Position-pos).Magnitude<1 then return end
	end
	s.count+=1
	local p=Instance.new("Part");p.Name=tostring(s.count);p.Size=Vector3.new(1,1,1)
	p.Transparency=1;p.Anchored=true;p.CanCollide=false;p.CanQuery=false;p.CanTouch=false
	p.CFrame=CFrame.new(pos);p.Parent=s.folder
	send(player,"RoadNodeV2",s.folder.Name,s.count,pos)
end
local function undoNodeV2(player)
	local s=v2Sessions[player];if not s or s.count<1 then return end
	local p=s.folder:FindFirstChild(tostring(s.count));if p then p:Destroy() end
	s.count-=1;send(player,"RoadUndoV2",s.folder.Name,s.count+1)
end
local function finishRoadV2(player)
	local s=v2Sessions[player];if not s then return end
	local name=s.folder.Name
	if s.count<2 then s.folder:Destroy();v2Sessions[player]=nil;send(player,"RoadCancelledV2",name);return end
	s.folder:SetAttribute("NodeCount",s.count)
	network:SetAttribute("Revision",(network:GetAttribute("Revision") or 0)+1)
	v2Sessions[player]=nil
	send(player,"RoadFinishedV2",name,s.count,false)
	print(("[RoadMapperServer] V2 ROAD %s: %d nodes F%d/R%d width=%.2f median=%.1f"):format(
		name,s.count,s.folder:GetAttribute("ForwardLanes"),s.folder:GetAttribute("ReverseLanes"),
		s.folder:GetAttribute("LaneWidth"),s.folder:GetAttribute("MedianWidth")))
end
local function listV2()
	local roads={}
	for _,f in ipairs(network:GetChildren()) do
		if f:IsA("Folder") and f~=junctionRoot and f:GetAttribute("RoadType") then
			local nodes={};local i=1
			while f:FindFirstChild(tostring(i)) do table.insert(nodes,f[tostring(i)].Position);i+=1 end
			table.insert(roads,{name=f.Name,roadType=f:GetAttribute("RoadType"),nodes=nodes,
				speedLimit=f:GetAttribute("SpeedLimit") or 25,laneWidth=f:GetAttribute("LaneWidth") or 3.4,
				forwardLanes=f:GetAttribute("ForwardLanes") or 1,reverseLanes=f:GetAttribute("ReverseLanes") or 1,
				medianWidth=f:GetAttribute("MedianWidth") or 0})
		end
	end
	local js={}
	for _,j in ipairs(junctionRoot:GetChildren()) do
		if j:IsA("BasePart") then table.insert(js,{name=j.Name,position=j.Position,control=j:GetAttribute("ControlType") or "Auto"}) end
	end
	return {roads=roads,junctions=js,revision=network:GetAttribute("Revision") or 0}
end
local function addJunctionV2(player,data)
	if typeof(data)~="table" or typeof(data.position)~="Vector3" then return end
	local p=Instance.new("Part");p.Name="Junction_"..(#junctionRoot:GetChildren()+1)
	p.Size=Vector3.new(1,1,1);p.Transparency=1;p.Anchored=true;p.CanCollide=false;p.CanQuery=false
	p.CFrame=CFrame.new(data.position);p:SetAttribute("ControlType",tostring(data.control or "Auto"));p.Parent=junctionRoot
	network:SetAttribute("Revision",(network:GetAttribute("Revision") or 0)+1)
	send(player,"JunctionChangedV2")
end
local function exportRoadsV2()
	print("========== ROADMAP_V2_BEGIN ==========")
	for _,r in ipairs(listV2().roads) do
		local pts={};for _,v in ipairs(r.nodes) do table.insert(pts,("{%.2f,%.2f,%.2f}"):format(v.X,v.Y,v.Z)) end
		print(('[ROAD] name="%s" type="%s" speed=%g laneWidth=%.2f forwardLanes=%d reverseLanes=%d median=%.1f traceForward=true nodes={%s}'):format(
			r.name,r.roadType,r.speedLimit,r.laneWidth,r.forwardLanes,r.reverseLanes,r.medianWidth,table.concat(pts,",")))
	end
	for _,j in ipairs(listV2().junctions) do
		print(('[JUNCTION] name="%s" control="%s" position={%.2f,%.2f,%.2f}'):format(j.name,j.control,j.position.X,j.position.Y,j.position.Z))
	end
	print(("========== ROADMAP_V2_END (%d roads, %d junctions) =========="):format(#listV2().roads,#listV2().junctions))
end

mapper.OnServerEvent:Connect(function(player, action, a, b)
	if not isDev(player) then
		return
	end
	if action == "NewRoad" then
		newRoad(player, a)
	elseif action == "AddNode" then
		addNode(player, a)
	elseif action == "UndoNode" then
		undoNode(player)
	elseif action == "FinishRoad" then
		finishRoad(player)
	elseif action == "DeleteRoad" then
		deleteRoad(player, a)
	elseif action == "CancelRoad" then
		local session = sessions[player]
		if session then
			session.folder:Destroy()
			sessions[player] = nil
			send(player, "Discarded", a)
		end
	elseif action == "NewRoadV2" then
		newRoadV2(player,a)
	elseif action == "AddNodeV2" then
		addNodeV2(player,a)
	elseif action == "UndoNodeV2" then
		undoNodeV2(player)
	elseif action == "FinishRoadV2" then
		finishRoadV2(player)
	elseif action == "CancelRoadV2" then
		local s=v2Sessions[player];if s then local n=s.folder.Name;s.folder:Destroy();v2Sessions[player]=nil;send(player,"RoadCancelledV2",n) end
	elseif action == "DeleteRoadV2" then
		local f=network:FindFirstChild(tostring(a));if f and f~=junctionRoot then f:Destroy();send(player,"RoadChangedV2") end
	elseif action == "AddJunctionV2" then
		addJunctionV2(player,a)
	elseif action == "ClearJunctionsV2" then
		junctionRoot:ClearAllChildren();send(player,"JunctionChangedV2")
	elseif action == "ResetRoadsV2" then
		for _,f in ipairs(network:GetChildren()) do if f:IsA("Folder") and f~=junctionRoot and f:GetAttribute("RoadType") then f:Destroy() end end
		junctionRoot:ClearAllChildren();network:SetAttribute("Revision",(network:GetAttribute("Revision") or 0)+1);send(player,"RoadResetV2")
	elseif action == "ExportRoadsV2" then
		exportRoadsV2()
	elseif action == "NewEscort" then
		newEscort(player)
	elseif action == "AddEscortNode" then
		addEscortNode(player, a)
	elseif action == "FinishEscort" then
		finishEscort(player)
	elseif action == "CancelEscort" then
		cancelEscort(player)
	end
end)

mapperQuery.OnServerInvoke = function(player, action)
	if not isDev(player) then
		return nil
	end
	if action == "List" then
		return listRoads()
	elseif action == "ListV2" then
		return listV2()
	end
	return nil
end

Players.PlayerAdded:Connect(function(player)
	if isDev(player) then
		task.wait(2)
		send(player, "Enable")
	end
end)
for _, player in ipairs(Players:GetPlayers()) do
	if isDev(player) then
		send(player, "Enable")
	end
end

Players.PlayerRemoving:Connect(function(player)
	sessions[player] = nil
	v2Sessions[player] = nil
	escortSessions[player] = nil
end)

local roadCount = 0
for _ in ipairs(network:GetChildren()) do
	roadCount += 1
end
print(("[RoadMapperServer] ready - %d road(s) total (%d loaded from seed data; fresh reset active)"):format(roadCount, seeded))

---------------------------------------------------------------------------
-- PRISON MAPPER (F7 client tool)
-- Runtime authoring helper for defining the CorrectionalFacility. Definitions
-- are intentionally printed to Studio Output so they can be baked into a
-- later build after the developer maps the facility.
---------------------------------------------------------------------------
local prisonMap = workspace:FindFirstChild("PrisonMap")
if not prisonMap then
	prisonMap = Instance.new("Folder")
	prisonMap.Name = "PrisonMap"
	prisonMap.Parent = workspace
end

local prisonFolders = {}
for _, kind in ipairs({"Zones", "Cells", "Points", "Doors"}) do
	local f = prisonMap:FindFirstChild(kind)
	if not f then
		f = Instance.new("Folder")
		f.Name = kind
		f.Parent = prisonMap
	end
	prisonFolders[kind] = f
end

local function prisonSafeName(value)
	value = tostring(value or "")
	value = value:gsub("[^%w_%-%s]", "")
	value = value:gsub("%s+", "_")
	if value == "" then value = "Unnamed" end
	return value:sub(1, 48)
end

local function prisonNextName(kind, category)
	local root = prisonFolders[kind]
	local base = prisonSafeName(category)
	local n = 1
	while root:FindFirstChild(base .. "_" .. n) do n += 1 end
	return base .. "_" .. n
end

local function prisonVec(v)
	return ("{%.2f, %.2f, %.2f}"):format(v.X, v.Y, v.Z)
end

local function prisonResolveTarget(inst)
	if typeof(inst) ~= "Instance" then return nil end
	local facility = workspace:FindFirstChild("CorrectionalFacility")
	if not facility or not inst:IsDescendantOf(facility) then return nil end
	local cur = inst
	while cur and cur ~= facility do
		local n = string.lower(cur.Name)
		if string.find(n, "door", 1, true) or string.find(n, "gate", 1, true) then
			if cur:IsA("BasePart") or cur:IsA("Model") then return cur end
		end
		cur = cur.Parent
	end
	if inst:IsA("BasePart") or inst:IsA("Model") then return inst end
	return nil
end

local function prisonTargetPosition(inst)
	if not inst then return nil end
	if inst:IsA("BasePart") then return inst.Position end
	if inst:IsA("Model") then return inst:GetPivot().Position end
	return nil
end

local function prisonMakeMarker(name, pos, parent)
	local p = Instance.new("Part")
	p.Name = name
	p.Size = Vector3.new(0.5, 0.5, 0.5)
	p.Transparency = 1
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CFrame = CFrame.new(pos)
	p.Parent = parent
	return p
end

local function prisonSaveZone(player, data)
	if typeof(data) ~= "table" or typeof(data.a) ~= "Vector3" or typeof(data.b) ~= "Vector3" then return end
	local category = prisonSafeName(data.category)
	local name = prisonSafeName(data.name)
	if name == "Unnamed" then name = prisonNextName("Zones", category) end
	if prisonFolders.Zones:FindFirstChild(name) then name = prisonNextName("Zones", category) end
	local minV = Vector3.new(math.min(data.a.X,data.b.X), math.min(data.a.Y,data.b.Y), math.min(data.a.Z,data.b.Z))
	local maxV = Vector3.new(math.max(data.a.X,data.b.X), math.max(data.a.Y,data.b.Y), math.max(data.a.Z,data.b.Z))
	local zone = Instance.new("Part")
	zone.Name = name
	zone.Anchored = true
	zone.CanCollide = false
	zone.CanQuery = false
	zone.Transparency = 1
	zone.Size = Vector3.new(math.max(0.5,maxV.X-minV.X), math.max(0.5,maxV.Y-minV.Y), math.max(0.5,maxV.Z-minV.Z))
	zone.CFrame = CFrame.new((minV+maxV)/2)
	zone:SetAttribute("MapKind", "Zone")
	zone:SetAttribute("Category", category)
	zone.Parent = prisonFolders.Zones
	print(("[PrisonMapper] ZONE %s category=%s min=%s max=%s"):format(name, category, prisonVec(minV), prisonVec(maxV)))
	send(player, "PrisonSaved", "Zone", name, category, minV, maxV)
end

local function prisonSaveCell(player, data)
	if typeof(data) ~= "table" or typeof(data.position) ~= "Vector3" then return end
	local category = prisonSafeName(data.category)
	local name = prisonSafeName(data.name)
	if name == "Unnamed" then name = prisonNextName("Cells", category) end
	if prisonFolders.Cells:FindFirstChild(name) then name = prisonNextName("Cells", category) end
	local folder = Instance.new("Folder")
	folder.Name = name
	folder:SetAttribute("MapKind", "Cell")
	folder:SetAttribute("Category", category)
	folder.Parent = prisonFolders.Cells
	prisonMakeMarker("StandPoint", data.position, folder)
	local door = prisonResolveTarget(data.door)
	if door then
		local ov = Instance.new("ObjectValue")
		ov.Name = "Door"
		ov.Value = door
		ov.Parent = folder
	end
	local doorText = door and door:GetFullName() or "NONE"
	print(("[PrisonMapper] CELL %s category=%s stand=%s door=%s"):format(name, category, prisonVec(data.position), doorText))
	send(player, "PrisonSaved", "Cell", name, category, data.position, prisonTargetPosition(door))
end

local function prisonSavePoint(player, data)
	if typeof(data) ~= "table" or typeof(data.position) ~= "Vector3" then return end
	local category = prisonSafeName(data.category)
	local name = prisonSafeName(data.name)
	if name == "Unnamed" then name = prisonNextName("Points", category) end
	if prisonFolders.Points:FindFirstChild(name) then name = prisonNextName("Points", category) end
	local p = prisonMakeMarker(name, data.position, prisonFolders.Points)
	p:SetAttribute("MapKind", "Point")
	p:SetAttribute("Category", category)
	print(("[PrisonMapper] POINT %s category=%s position=%s"):format(name, category, prisonVec(data.position)))
	send(player, "PrisonSaved", "Point", name, category, data.position)
end

local function prisonSaveDoor(player, data)
	if typeof(data) ~= "table" then return end
	local door = prisonResolveTarget(data.door)
	if not door then return end
	local doorType = prisonSafeName(data.doorType or data.category or "Normal")
	local security = prisonSafeName(data.security or "General")
	local access = prisonSafeName(data.access or "PrisonStaff")
	local direction = prisonSafeName(data.direction or "BothWays")
	local name = prisonSafeName(data.name)
	if name == "Unnamed" then name = prisonNextName("Doors", doorType) end
	if prisonFolders.Doors:FindFirstChild(name) then name = prisonNextName("Doors", doorType) end
	local folder = Instance.new("Folder")
	folder.Name = name
	folder:SetAttribute("MapKind", "Door")
	folder:SetAttribute("Category", doorType)
	folder:SetAttribute("DoorType", doorType)
	folder:SetAttribute("Security", security)
	folder:SetAttribute("Access", access)
	folder:SetAttribute("Direction", direction)
	folder:SetAttribute("IsExit", doorType == "Exit" or doorType == "EmergencyExit")
	folder:SetAttribute("IsVehicleGate", doorType == "VehicleGate")
	folder.Parent = prisonFolders.Doors
	local ov = Instance.new("ObjectValue")
	ov.Name = "Target"
	ov.Value = door
	ov.Parent = folder
	local pos = prisonTargetPosition(door) or Vector3.zero
	print(("[PrisonMapper] DOOR %s type=%s security=%s access=%s direction=%s target=%s position=%s"):format(name, doorType, security, access, direction, door:GetFullName(), prisonVec(pos)))
	send(player, "PrisonSaved", "Door", name, doorType, pos)
end


-- Baked prison definitions supplied from the developer's mapper session.
-- These are recreated every server start so subsequent AI systems can use them
-- without relying on the previous Studio play session still existing.
local function prisonNearestDoor(position, maxDistance)
	local facility = workspace:FindFirstChild("CorrectionalFacility")
	if not facility then return nil end
	local best, bestDist = nil, maxDistance or 14
	for _, obj in ipairs(facility:GetDescendants()) do
		if obj:IsA("BasePart") or obj:IsA("Model") then
			local n = string.lower(obj.Name)
			if string.find(n, "door", 1, true) or string.find(n, "gate", 1, true) then
				local pos = prisonTargetPosition(obj)
				if pos then
					local d = (pos - position).Magnitude
					if d < bestDist then best, bestDist = obj, d end
				end
			end
		end
	end
	return best
end

local function seedPrisonMap()
	-- Intake zone: mapper clicks were floor-level, so make this a useful
	-- full-height volume instead of a 0.01-stud-tall sheet.
	if not prisonFolders.Zones:FindFirstChild("Intake_1") then
		local minV = Vector3.new(3960.71, -1.5, -2151.24)
		local maxV = Vector3.new(3992.61, 16.0, -2124.48)
		local zone = Instance.new("Part")
		zone.Name = "Intake_1"
		zone.Anchored = true; zone.CanCollide = false; zone.CanQuery = false; zone.Transparency = 1
		zone.Size = maxV - minV; zone.CFrame = CFrame.new((minV + maxV) / 2)
		zone:SetAttribute("MapKind", "Zone"); zone:SetAttribute("Category", "Intake")
		zone.Parent = prisonFolders.Zones
	end

	if not prisonFolders.Cells:FindFirstChild("IntakeCell_1") then
		local folder = Instance.new("Folder")
		folder.Name = "IntakeCell_1"; folder:SetAttribute("MapKind", "Cell"); folder:SetAttribute("Category", "IntakeCell")
		folder.Parent = prisonFolders.Cells
		local stand = Vector3.new(3981.56, 0.42, -2120.14)
		prisonMakeMarker("StandPoint", stand, folder)
		local door = prisonNearestDoor(stand, 10)
		if door then local ov=Instance.new("ObjectValue"); ov.Name="Door"; ov.Value=door; ov.Parent=folder end
	end


	-- v84: baked booking cells from the original prison workflow.  Earlier
	-- builds only seeded IntakeCell_1, so the Booking Officer had nowhere to
	-- transfer an inmate after every fresh Team Test.
	local bookingSeeds={
		Vector3.new(3953.29,0.42,-2120.37),Vector3.new(3953.69,0.42,-2107.85),
		Vector3.new(3952.44,0.62,-2078.34),Vector3.new(3953.56,0.42,-2092.67),
		Vector3.new(3952.52,0.42,-2067.03),
	}
	for i,stand in ipairs(bookingSeeds) do
		local name="BookingCell_"..i
		if not prisonFolders.Cells:FindFirstChild(name) then
			local folder=Instance.new("Folder");folder.Name=name;folder:SetAttribute("MapKind","Cell");folder:SetAttribute("Category","BookingCell");folder.Parent=prisonFolders.Cells
			prisonMakeMarker("StandPoint",stand,folder)
			local door=prisonNearestDoor(stand,10)
			if door then local ov=Instance.new("ObjectValue");ov.Name="Door";ov.Value=door;ov.Parent=folder end
		end
	end

	local doorSeeds = {
		{ name="Normal_1", type="Normal", security="General", access="PrisonStaff", direction="BothWays", pos=Vector3.new(3966.49,1.02,-2124.03) },
		-- This is the secure intake entrance used for vehicle-dropoff handoff.
		{ name="IntakeEntrance_1", type="IntakeEntrance", security="High", access="PoliceAndPrisonStaff", direction="BothWays", pos=Vector3.new(3993.29,3.92,-2148.19) },
		{ name="Exit_2", type="Exit", security="High", access="PrisonStaff", direction="BothWays", pos=Vector3.new(4016.26,3.77,-2140.54) },
	}
	for _, seed in ipairs(doorSeeds) do
		if not prisonFolders.Doors:FindFirstChild(seed.name) then
			local target = prisonNearestDoor(seed.pos, 12)
			if target then
				local folder=Instance.new("Folder"); folder.Name=seed.name; folder.Parent=prisonFolders.Doors
				folder:SetAttribute("MapKind","Door"); folder:SetAttribute("Category",seed.type); folder:SetAttribute("DoorType",seed.type)
				folder:SetAttribute("Security",seed.security); folder:SetAttribute("Access",seed.access); folder:SetAttribute("Direction",seed.direction)
				folder:SetAttribute("IsExit", seed.type=="Exit" or seed.type=="EmergencyExit")
				folder:SetAttribute("IsVehicleGate", seed.type=="VehicleGate")
				folder:SetAttribute("IsIntakeEntrance", seed.type=="IntakeEntrance")
				local ov=Instance.new("ObjectValue"); ov.Name="Target"; ov.Value=target; ov.Parent=folder
			end
		end
	end

	-- Default role markers until the developer places more precise ones.
	if not prisonFolders.Points:FindFirstChild("IntakeOfficerPost_1") then
		local p=prisonMakeMarker("IntakeOfficerPost_1", Vector3.new(3985.5,0.42,-2138.0), prisonFolders.Points)
		p:SetAttribute("MapKind","Point"); p:SetAttribute("Category","IntakeOfficerPost")
	end
	if not prisonFolders.Points:FindFirstChild("PoliceHandoff_1") then
		local p=prisonMakeMarker("PoliceHandoff_1", Vector3.new(3997.0,0.42,-2148.0), prisonFolders.Points)
		p:SetAttribute("MapKind","Point"); p:SetAttribute("Category","PoliceHandoff")
	end

	local roleSeeds={
		{"BookingOfficerPost_1","BookingOfficerPost",Vector3.new(3942.0,0.42,-2134.0)},
		{"ClassificationOfficerPost_1","ClassificationOfficerPost",Vector3.new(3954.0,0.42,-2070.0)},
		{"ClassificationPoint_1","ClassificationPoint",Vector3.new(3950.5,0.42,-2058.0)},
		{"HousingOfficerPost_1","HousingOfficerPost",Vector3.new(3956.0,0.42,-2065.0)},
	}
	for _,seed in ipairs(roleSeeds) do
		if not prisonFolders.Points:FindFirstChild(seed[1]) then
			local p=prisonMakeMarker(seed[1],seed[3],prisonFolders.Points);p:SetAttribute("MapKind","Point");p:SetAttribute("Category",seed[2])
		end
	end
end

seedPrisonMap()

mapper.OnServerEvent:Connect(function(player, action, data)
	if not isDev(player) then return end
	if action == "PrisonSaveZone" then
		prisonSaveZone(player, data)
	elseif action == "PrisonSaveCell" then
		prisonSaveCell(player, data)
	elseif action == "PrisonSavePoint" then
		prisonSavePoint(player, data)
	elseif action == "PrisonSaveDoor" then
		prisonSaveDoor(player, data)
	elseif action == "PrisonClearSession" then
		-- Client-only selection state; this action exists for future compatibility.
	end
end)

print("[PrisonMapper] ready - P/F7 mapper; seeded intake, booking and processing handoff points")
